<script setup lang="ts">
definePageMeta({middleware:['auth','supplier']})
const route=useRoute(); const supabase=useSupabaseClient(); const {company,user,loadProfile}=useProfile(); const loading=ref(true), saving=ref(false), errorMessage=ref(''), message=ref(''); const files=ref<File[]>([]); const existingImages=ref<any[]>([])
const form=reactive<any>({title:'',vehicle_year:'',vehicle_make:'',vehicle_model:'',vehicle_variant:'',category:'',condition:'used',oem_number:'',colour:'',price:'',currency:'AUD',quantity:1,country_code:'AU',state_region:'',city:'',description:'',status:'active'})
const load=async()=>{loading.value=true;try{await loadProfile();const {data,error}=await supabase.from('parts').select('*,part_images(id,image_url,sort_order)').eq('id',route.params.id).single();if(error)throw error;if(data.seller_company_id!==company.value?.id)throw new Error('You do not have access to this listing.');Object.assign(form,data);existingImages.value=(data.part_images||[]).sort((a:any,b:any)=>a.sort_order-b.sort_order)}catch(e:any){errorMessage.value=e.message}finally{loading.value=false}}
onMounted(load); const onFiles=(e:any)=>files.value=Array.from(e.target.files||[])
const removeImage=async(img:any)=>{const {error}=await supabase.from('part_images').delete().eq('id',img.id);if(error){errorMessage.value=error.message;return}existingImages.value=existingImages.value.filter(x=>x.id!==img.id)}
const save=async()=>{saving.value=true;errorMessage.value='';message.value='';try{const payload:any={...form};delete payload.id;delete payload.created_at;delete payload.updated_at;delete payload.created_by;delete payload.seller_company_id;delete payload.part_images;delete payload.vehicle_id;payload.vehicle_year=payload.vehicle_year?Number(payload.vehicle_year):null;payload.price=payload.price===''?null:Number(payload.price);payload.quantity=Number(payload.quantity||0);payload.updated_at=new Date().toISOString();const {error}=await supabase.from('parts').update(payload).eq('id',route.params.id);if(error)throw error;for(let i=0;i<files.value.length;i++){const file=files.value[i];const safe=file.name.replace(/[^a-zA-Z0-9._-]/g,'-');const path=`${user.value!.id}/${route.params.id}/${Date.now()}-${i}-${safe}`;const {error:upErr}=await supabase.storage.from('part-images').upload(path,file);if(upErr)throw upErr;const url=supabase.storage.from('part-images').getPublicUrl(path).data.publicUrl;const {error:imgErr}=await supabase.from('part_images').insert({part_id:route.params.id,image_url:url,sort_order:existingImages.value.length+i});if(imgErr)throw imgErr}files.value=[];await load();message.value='Listing updated.'}catch(e:any){errorMessage.value=e.message}finally{saving.value=false}}
</script>
<template><section class="section"><div class="container" style="max-width:900px;"><div class="kicker">Supplier inventory</div><h1 class="page-title" style="margin-top:8px;">Edit Part</h1><div v-if="loading" class="card" style="padding:24px;margin-top:22px;">Loading…</div><form v-else class="card" style="padding:24px;margin-top:22px;" @submit.prevent="save"><div v-if="message" class="notice success">{{message}}</div><div v-if="errorMessage" class="notice error">{{errorMessage}}</div><div class="grid grid-2"><div><label class="label">Part title</label><input v-model="form.title" class="input" required></div><div><label class="label">OEM / Part Number</label><input v-model="form.oem_number" class="input"></div><div><label class="label">Year</label><input v-model="form.vehicle_year" class="input" type="number"></div><div><label class="label">Make</label><input v-model="form.vehicle_make" class="input"></div><div><label class="label">Model</label><input v-model="form.vehicle_model" class="input"></div><div><label class="label">Variant</label><input v-model="form.vehicle_variant" class="input"></div><div><label class="label">Category</label><input v-model="form.category" class="input"></div><div><label class="label">Condition</label><select v-model="form.condition" class="select"><option value="new">New</option><option value="used">Used</option><option value="refurbished">Refurbished</option><option value="aftermarket">Aftermarket</option></select></div><div><label class="label">Colour</label><input v-model="form.colour" class="input"></div><div><label class="label">Price</label><input v-model="form.price" class="input" type="number" step="0.01"></div><div><label class="label">Quantity</label><input v-model="form.quantity" class="input" type="number" min="0"></div><div><label class="label">Status</label><select v-model="form.status" class="select"><option value="active">Active</option><option value="draft">Draft</option><option value="sold">Sold</option></select></div><div><label class="label">City</label><input v-model="form.city" class="input"></div><div><label class="label">State / Region</label><input v-model="form.state_region" class="input"></div></div><div style="margin-top:18px;"><label class="label">Description</label><textarea v-model="form.description" class="textarea" rows="5"></textarea></div><div style="margin-top:18px;"><label class="label">Existing photos</label><div class="image-grid"><div v-for="img in existingImages" :key="img.id" class="image-tile"><img :src="img.image_url"><button type="button" class="btn btn-danger small-btn" @click="removeImage(img)">Remove</button></div></div></div><div style="margin-top:18px;"><label class="label">Add more photos</label><input class="input" type="file" accept="image/*" multiple @change="onFiles"></div><button class="btn btn-primary" style="margin-top:20px;" :disabled="saving">{{saving?'Saving…':'Save Changes'}}</button></form></div></section></template>
